"use client";

/**
 * Line trace: a line chart draws itself left to right over a soft area fill,
 * a dot riding its leading edge, and the final value is called out where the
 * line ends. The trend beat of a product film.
 *
 * Written by Better Design. Painted from the theme prop, so the line, dot and
 * fill take the product's primary colour.
 */
import { useId } from "react";
import { loadFont } from "@remotion/google-fonts/Inter";
import { getLength, getPointAtLength } from "@remotion/paths";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

const TRACE_AT = 12;
const TRACE_FRAMES = 66;
const CALLOUT_AT = 72;

const W = 1380;
const H = 520;
/** Room above the highest point, so the callout never clips. */
const HEADROOM = 120;

export interface LineTraceProps {
  /** The series, left to right. Two or more values. */
  points?: number[];
  /** The line above the chart that says what is measured. */
  label?: string;
  prefix?: string;
  suffix?: string;
  /** Digits after the decimal point on the final value. */
  decimals?: number;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** A smooth path through the points, as cubic curves (Catmull-Rom). */
function smoothPath(pts: Array<[number, number]>): string {
  let d = `M ${pts[0][0]} ${pts[0][1]}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[Math.min(pts.length - 1, i + 2)];
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += ` C ${c1[0]} ${c1[1]} ${c2[0]} ${c2[1]} ${p2[0]} ${p2[1]}`;
  }
  return d;
}

/** Draw a line chart left to right with a riding dot and an end callout. */
export function LineTrace({
  points = [18, 22, 20, 27, 25, 33, 31, 40, 46],
  label = "Weekly active users",
  prefix = "",
  suffix = "k",
  decimals = 0,
  theme: themeOverride,
  font,
}: LineTraceProps) {
  const theme = useVideoTheme(themeOverride);
  // Two charts in one frame, as in a cross-fade, each need their own gradient and clip.
  const uid = useId().replace(/[^a-zA-Z0-9-]/g, "");
  const fillId = `line-trace-fill-${uid}`;
  const clipId = `line-trace-clip-${uid}`;
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const series = points.length >= 2 ? points : [0, ...points, 0].slice(0, 2);
  const lo = Math.min(...series);
  const hi = Math.max(...series);
  const span = hi - lo || 1;
  const pts = series.map((v, i): [number, number] => [
    (i / (series.length - 1)) * W,
    HEADROOM + (1 - (v - lo) / span) * (H - HEADROOM - 40),
  ]);
  const d = smoothPath(pts);
  const length = getLength(d);

  const enter = easings.out(interpolate(frame, [0, 16], [0, 1], clamp));
  const trace = easings.inOut(interpolate(frame, [TRACE_AT, TRACE_AT + TRACE_FRAMES], [0, 1], clamp));
  const head = getPointAtLength(d, Math.max(0.001, length * trace)) ?? { x: pts[0][0], y: pts[0][1] };
  const calloutT = easings.out(interpolate(frame, [CALLOUT_AT, CALLOUT_AT + 18], [0, 1], clamp));

  const last = series[series.length - 1];
  const finalText = `${prefix}${last.toLocaleString("en-US", { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}${suffix}`;
  const end = pts[pts.length - 1];
  const area = `${d} L ${W} ${H} L 0 ${H} Z`;

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ width: W, display: "flex", flexDirection: "column", gap: 40 }}>
        <div style={{ fontSize: 44, fontWeight: 600, letterSpacing: "-0.02em", color: theme.foreground, opacity: enter, transform: `translateY(${(1 - enter) * 16}px)` }}>
          {label}
        </div>
        <div style={{ position: "relative", width: W, height: H }}>
          <svg width={W} height={H} style={{ overflow: "visible" }}>
            <defs>
              <linearGradient id={fillId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={withAlpha(theme.primary, 0.22)} />
                <stop offset="100%" stopColor={withAlpha(theme.primary, 0)} />
              </linearGradient>
              <clipPath id={clipId}>
                <rect x={-20} y={-40} width={head.x + 20} height={H + 80} />
              </clipPath>
            </defs>
            {[0, 0.33, 0.66, 1].map((g) => (
              <line key={g} x1={0} x2={W} y1={HEADROOM + g * (H - HEADROOM)} y2={HEADROOM + g * (H - HEADROOM)} stroke={withAlpha(theme.foreground, (g === 1 ? 0.18 : 0.06) * enter)} strokeWidth={g === 1 ? 2 : 1} />
            ))}
            <g clipPath={`url(#${clipId})`}>
              <path d={area} fill={`url(#${fillId})`} />
              <path d={d} fill="none" stroke={theme.primary} strokeWidth={7} strokeLinecap="round" strokeLinejoin="round" />
            </g>
            {trace > 0 && (
              <>
                <circle cx={head.x} cy={head.y} r={26} fill={withAlpha(theme.primary, 0.16)} />
                <circle cx={head.x} cy={head.y} r={13} fill={theme.primary} stroke={theme.background} strokeWidth={5} />
              </>
            )}
          </svg>
          <div
            style={{
              position: "absolute",
              left: end[0],
              top: end[1] - 44,
              transform: `translate(-100%, -100%) translateY(${(1 - calloutT) * 14}px)`,
              opacity: calloutT,
              background: theme.card,
              color: theme.cardForeground,
              border: `1px solid ${theme.border}`,
              borderRadius: theme.radius * 1.4,
              padding: "14px 26px",
              fontSize: 56,
              fontWeight: 700,
              letterSpacing: "-0.03em",
              fontVariantNumeric: "tabular-nums",
              whiteSpace: "nowrap",
              boxShadow: `0 10px 30px ${withAlpha(theme.foreground, 0.08)}`,
            }}
          >
            {finalText}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}
